-- 시연용 구성도 자료 (명세 4.5 REQ-504~511, slices/8a, 명세 7장 시연 도구). scripts/demo-diagram-data.py가 만든 파일이다. 직접 고치지 않는다
-- 구성도 4개, 판 16개, 권한 16줄. 장비 상자는 시드 장비(R__seed_initial_equipment) 31대. 내용은 모두 가상(NFR-002)
-- 이름이 R__seed_work_diagram_demo라 초기 데이터·장비 다음에 돈다. 구성도가 하나라도 있거나 번호 범위(600001~)가 쓰였거나
-- 쓸 계정(사용 중)·부서(사용 중)·장비(번호·부서·이름이 시드와 같음)가 하나라도 없거나 만든 사람의 소속이 주인 부서가 아니면 전체를 건너뛴다
-- 시각은 시연 기준 시각 2026-11-02 12:00:00(KST)보다 앞의 고정 값이다. 편집 잠금·임시본은 넣지 않는다

SET @a_bn1_cmdr = (SELECT id FROM account WHERE login_id = 'bn1-cmdr' AND active = TRUE);
SET @p_bn1_cmdr = (SELECT a.personnel_id FROM account a JOIN personnel p ON p.id = a.personnel_id WHERE a.login_id = 'bn1-cmdr' AND a.active = TRUE AND p.active = TRUE AND p.department_id = 1);
SET @a_bn1_co1_admin = (SELECT id FROM account WHERE login_id = 'bn1-co1-admin' AND active = TRUE);
SET @p_bn1_co1_admin = (SELECT a.personnel_id FROM account a JOIN personnel p ON p.id = a.personnel_id WHERE a.login_id = 'bn1-co1-admin' AND a.active = TRUE AND p.active = TRUE AND p.department_id = 5);
SET @a_bn1_co1_cmdr = (SELECT id FROM account WHERE login_id = 'bn1-co1-cmdr' AND active = TRUE);
SET @p_bn1_co1_cmdr = (SELECT a.personnel_id FROM account a JOIN personnel p ON p.id = a.personnel_id WHERE a.login_id = 'bn1-co1-cmdr' AND a.active = TRUE AND p.active = TRUE AND p.department_id = 2);
SET @a_bn1_co1_s1_lead = (SELECT id FROM account WHERE login_id = 'bn1-co1-s1-lead' AND active = TRUE);
SET @p_bn1_co1_s1_lead = (SELECT a.personnel_id FROM account a JOIN personnel p ON p.id = a.personnel_id WHERE a.login_id = 'bn1-co1-s1-lead' AND a.active = TRUE AND p.active = TRUE AND p.department_id = 5);
SET @a_bn1_co1_s1_m1 = (SELECT id FROM account WHERE login_id = 'bn1-co1-s1-m1' AND active = TRUE);
SET @p_bn1_co1_s1_m1 = (SELECT a.personnel_id FROM account a JOIN personnel p ON p.id = a.personnel_id WHERE a.login_id = 'bn1-co1-s1-m1' AND a.active = TRUE AND p.active = TRUE AND p.department_id = 5);
SET @a_bn2_cmdr = (SELECT id FROM account WHERE login_id = 'bn2-cmdr' AND active = TRUE);
SET @p_bn2_cmdr = (SELECT a.personnel_id FROM account a JOIN personnel p ON p.id = a.personnel_id WHERE a.login_id = 'bn2-cmdr' AND a.active = TRUE AND p.active = TRUE AND p.department_id = 11);
SET @a_sysadmin = (SELECT id FROM account WHERE login_id = 'sysadmin' AND active = TRUE);
SET @p_sysadmin = (SELECT a.personnel_id FROM account a JOIN personnel p ON p.id = a.personnel_id WHERE a.login_id = 'sysadmin' AND a.active = TRUE AND p.active = TRUE AND p.department_id = 1);
SET @ok = (SELECT COUNT(*) FROM diagram) = 0
    AND (SELECT COUNT(*) FROM diagram_grant WHERE id >= 600001) = 0
    AND (SELECT COUNT(*) FROM diagram_version WHERE id >= 600001) = 0
    AND (SELECT COUNT(*) FROM department WHERE id IN (1, 2, 3, 5, 6, 11, 12) AND active = TRUE) = 7
    AND (SELECT COUNT(*) FROM equipment WHERE (id, department_id, name) IN ((1, 5, '휴대용 무전기 1호'), (2, 5, '야전 발전기 1호'), (3, 5, '업무용 노트북 1호'), (1001, 5, '행정용 PC 1호'), (1002, 5, '행정용 PC 2호'), (1003, 5, '업무용 노트북 13호'), (1004, 5, '레이저 프린터 1호'), (1005, 5, '차량용 무전기 1호'), (1006, 5, '소형 스위치 1호'), (1007, 5, '소형 발전기 1호'), (1010, 6, '휴대용 무전기 13호'), (1011, 6, '차량용 무전기 2호'), (1012, 6, '소형 스위치 2호'), (1013, 6, '무정전 전원장치 1호'), (1085, 2, '복합기 1호'), (1086, 2, '영상회의 단말 1호'), (1087, 2, '행정용 PC 15호'), (1103, 1, '업무 서버 1호'), (1104, 1, '업무 서버 2호'), (1105, 1, '라우터 1호'), (1106, 1, '방화벽 1호'), (1107, 1, '저장장치(NAS) 1호'), (1108, 1, 'CCTV 녹화기 1호'), (1109, 1, '영상회의 서버 1호'), (1110, 11, '업무 서버 3호'), (1111, 11, '업무 서버 4호'), (1112, 11, '라우터 2호'), (1113, 11, '방화벽 2호'), (1114, 11, '저장장치(NAS) 2호'), (1115, 11, 'CCTV 녹화기 2호'), (1116, 11, '영상회의 서버 2호'))) = 31
    AND @a_bn1_cmdr IS NOT NULL AND @p_bn1_cmdr IS NOT NULL
    AND @a_bn1_co1_admin IS NOT NULL AND @p_bn1_co1_admin IS NOT NULL
    AND @a_bn1_co1_cmdr IS NOT NULL AND @p_bn1_co1_cmdr IS NOT NULL
    AND @a_bn1_co1_s1_lead IS NOT NULL AND @p_bn1_co1_s1_lead IS NOT NULL
    AND @a_bn1_co1_s1_m1 IS NOT NULL AND @p_bn1_co1_s1_m1 IS NOT NULL
    AND @a_bn2_cmdr IS NOT NULL AND @p_bn2_cmdr IS NOT NULL
    AND @a_sysadmin IS NOT NULL AND @p_sysadmin IS NOT NULL;

